 static int checks;static void check(boolean b,String text){if(!b)throw new AssertionError(text);checks++;}interface Work{void run()throws Exception;}static void fails(Work work,String text)throws Exception{try{work.run();}catch(Exception e){check(true,text);return;}throw new AssertionError(text);}static void await(CompletionStage<?> stage)throws Exception{stage.toCompletableFuture().get(5,TimeUnit.SECONDS);}
