  UUID id=UUID.randomUUID(),seller=UUID.randomUUID(),buyer=UUID.randomUUID(),actor=UUID.randomUUID();var terms=new TechLicense.Terms(id,seller,buyer,actor,"irrigation",2,.15,12500,3600);var offer=TechLicense.offered(terms,86400,1000);
