  var holder=new Thread(()->{lock.lock();entered.countDown();try{release.await(5,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}finally{lock.unlock();}});holder.start();check(entered.await(1,TimeUnit.SECONDS),"physical license writer lock held");var before=repo.rows();var commit=repo.commit(before,Map.of(id,funding));check(!commit.toCompletableFuture().isDone()&&repo.rows()==before&&repo.busy(),"before ACK funding intent is neither published nor available for execution");check(SuiteState.tryRun("license ack contention",()->{}),"disk wait leaves shared Suite available");fails(()->await(repo.commit(before,Map.of(id,active))),"concurrent result cannot bypass durable funding intent");release.countDown();await(commit);holder.join();check(repo.rows().get(id).phase()==ACCEPTING,"acceptance publishes only after actual durable ACK");
