  await(restart.commit(restart.rows(),Map.of(id,paying.phase(PAY_REVIEW,"no automatic payout retry"))));await(restart.closeAsync());check(Arrays.equals(oldBytes,Files.readAllBytes(oldPath)),"new licenses never modify permanent learned technologies or active research bytes");var oldReload=new ResearchRepository(oldPath);oldReload.load();check(oldReload.get(seller).equals(state),"existing learned levels and started study survive license lifecycle unchanged");
  var badPath=folder.resolve("broken.yml");Files.writeString(badPath,"schema: 99\nlicenses: {}\n");var damaged=new LicenseRepository(badPath);fails(damaged::load,"unknown license schema fails closed");fails(()->await(damaged.commit(damaged.rows(),Map.of(id,active))),"unread license data cannot be overwritten");await(damaged.closeAsync());check(Files.readString(badPath).contains("99"),"shutdown preserves unread license journal");
